 {view==='deals'&&<><div className="view-tabs"><Tabs value={filter} onValueChange={setFilter}><TabsList>{[{id:'open',label:'Pågående'},...OUTCOMES].map(p=><TabsTrigger key={p.id} value={p.id}>{p.label} <span className="tab-count">{deals.filter(d=>p.id==='open'?isOpen(d):d.stage===p.id).length}</span></TabsTrigger>)}</TabsList></Tabs><small>Dra ett kort för att föreslå nytt steg. Bekräfta i affären.</small></div>{filter==='open'?<div className="board">{PIPELINE.map((p,i)=><section className="column" data-stage={p.id} key={p.id} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();const d=st.deals.find(d=>d.id===e.dataTransfer.getData('text/plain'));if(d&&d.stage!==p.id)open('deal',{...d,stage:p.id})}}><div className="column-head"><span className={'stage-dot stage-'+i}/><b>{p.short}</b><span>{deals.filter(d=>d.stage===p.id).length}</span></div><div className="column-total">{sek(deals.filter(d=>d.stage===p.id).reduce((a,d)=>a+(d.value||0),0))}</div>{deals.filter(d=>d.stage===p.id).map(d=><button key={d.id} className="deal-card" draggable onDragStart={e=>e.dataTransfer.setData('text/plain',d.id)} onClick={()=>open('deal',d)}><small>{cname(d.customerId)}</small><h3>{d.title}</h3><span className="category">{d.category}</span><div className="deal-value"><b>{sek(d.value)}</b><span className="avatar">{d.owner.split(' ').map(s=>s[0]).join('')}</span></div><div className={'deal-next '+(d.nextDate<day()?'late':'')}><Clock size={13}/><span>{d.nextAction}<small>{dateLabel(d.nextDate)}</small></span></div></button>)}<button className="add-in-column" onClick={()=>{create('deal');/* New opportunities begin with required discovery. */}}><Plus size={14}/>Lägg till affär</button></section>)}</div>:<div className="panel">{deals.filter(d=>d.stage===filter).length?deals.filter(d=>d.stage===filter).map(d=><button className="list-row" key={d.id} onClick={()=>d.stage==='won'?open('order',st.orders.find(o=>o.dealId===d.id)!):open('deal',d)}><div><b>{d.title}</b><small>{cname(d.customerId)} · {d.reason||'Öppna leveransuppföljning'}</small></div><b>{sek(d.value)}</b><ArrowUpRight size={16}/></button>):<Empty>Inga affärer i det här urvalet.</Empty>}</div>}</>}
 {view==='customers'&&<section className="panel"><div className="panel-head"><h2>Kundregister <span className="count">{customers.length}</span></h2><Button size="sm" variant="outline" onClick={()=>setView('settings')}>Importera / exportera</Button></div>{customers.length?<Table><TableHeader><TableRow>{['Kund / kontakt','Relation','Ansvarig','Nästa avstämning','Öppna affärer',''].map(x=><TableHead key={x}>{x}</TableHead>)}</TableRow></TableHeader><TableBody>{customers.map(c=><TableRow key={c.id}><TableCell><button className="customer-name" onClick={()=>showCustomer(c.id)}><span className="company-icon">{short(c.name).slice(0,2).toUpperCase()}</span><span><b>{short(c.name)}</b><small>{c.contact||'Kontaktperson saknas'}</small></span></button></TableCell><TableCell><span data-status={c.status} className={'pill '+(concerns(c,day(),st||undefined).length?'amber':'')}>{label(RELATIONS,c.status)}</span></TableCell><TableCell>{c.owner}</TableCell><TableCell className={c.nextReview&&c.nextReview<day()?'late':''}>{dateLabel(c.nextReview)}</TableCell><TableCell>{st.deals.filter(d=>d.customerId===c.id&&isOpen(d)).length}</TableCell><TableCell><Button size="icon" variant="ghost" aria-label={'Öppna '+c.name} onClick={()=>showCustomer(c.id)}><ArrowUpRight size={16}/></Button></TableCell></TableRow>)}</TableBody></Table>:<Empty><p>Inga kunder i urvalet.</p><Button onClick={()=>create('customer')}>Lägg till första kunden</Button></Empty>}</section>}
 {['prospects','onboarding','care'].includes(view)&&<CustomerWorkflows key={view+'-'+space} mode={view as 'prospects'|'onboarding'|'care'} st={st} customers={customers} busy={busy} onSave={save} onCustomer={showCustomer} onCreateCustomer={()=>create('customer')} onDeal={d=>d.stage==='won'?open('order',st.orders.find(o=>o.dealId===d.id)!):open('deal',d)} onNewDeal={(c,type)=>type==='repeat'?setRepeatCustomer(c.id):open('deal',DealSchema.parse({customerId:c.id,owner:c.owner,type,title:c.plan.nextNeed||'Ny affär',need:c.plan.nextNeed||c.need,decisionMaker:c.decisionMaker,deliveryDate:c.plan.nextNeedDate,nextAction:'Stäm av behov och omfattning med kunden',nextDate:day()}))}/>}
 {view==='year'&&<YearWheel st={st} customers={customers} save={save} busy={busy} onCustomer={showCustomer}/>}
