 {['print','warehouse','orders'].includes(view)&&<ProductionBoard key={view+space} owner={owner} st={st} space={space} mode={view==='orders'?'sales':view as 'print'|'warehouse'} save={save} busy={busy} onOrder={o=>open('order',o)}/>}
